"use strict";
document.addEventListener('DOMContentLoaded',()=>{const dialog=document.createElement('dialog');dialog.id='imagePreview';dialog.setAttribute('aria-label','Bild in voller Qualität');dialog.innerHTML='<button type="button" autofocus>Schließen ×</button><img alt="Vergrößertes Bauplanbild"/>';document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.onclick=e=>{if(e.target===dialog)dialog.close();};document.addEventListener('click',event=>{const link=event.target.closest('a.gallery-frame');if(!link)return;const url=new URL(link.href,location.href);if(url.origin!==location.origin||!url.pathname.startsWith('/media/'))return;event.preventDefault();dialog.querySelector('img').src=url.href;dialog.showModal();});});
